/* Bitsy 0.2 compact Vulkan executor: bindless device addresses, one descriptor
 * set, three pipelines (fused/gemm/reduce), timeline capture/replay. */
#include "rt_internal.h"

#ifdef RT_WITH_VULKAN
#include <vulkan/vulkan.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Embedded SPIR-V, generated by CMake into build/generated/rt_*.spv.h */
#include "rt_fused.spv.h"
#include "rt_gemm.spv.h"
#include "rt_reduce.spv.h"

#define RT_NBUF 512

typedef struct {
  VkBuffer buf;
  VkDeviceMemory mem;
  VkDeviceAddress addr;
  VkDeviceSize size;
  int used;
} RtVkBuf;

struct RtVk {
  VkInstance inst;
  VkPhysicalDevice phys;
  VkDevice dev;
  VkQueue queue;
  uint32_t qfam;
  VkCommandPool pool;
  VkCommandBuffer cmd;
  VkFence fence;
  VkDescriptorSetLayout set_layout;
  VkDescriptorPool dpool;
  VkDescriptorSet set;
  VkPipelineLayout playout;
  VkPipeline fused[1];
  VkPipeline gemm[3];       /* tile variants: 16,32,64 */
  VkPipeline reduce;
  VkPipelineCache pcache;
  RtVkBuf bufs[RT_NBUF];
  VkBuffer params;
  VkDeviceMemory params_mem;
  void* params_map;
  VkBuffer out;
  VkDeviceMemory out_mem;
  void* out_map;
  int recording;
  VkSemaphore timeline;
  uint64_t tick;
  VkCommandBuffer replay_cmd;
  int replay_count;
};

static void* spv_data(const unsigned char* h, size_t* n) { (void)h; (void)n; return NULL; }

static int select_phys(RtVk* vk) {
  uint32_t n = 0;
  vkEnumeratePhysicalDevices(vk->inst, &n, NULL);
  if (!n) return -1;
  VkPhysicalDevice* list = (VkPhysicalDevice*)malloc(sizeof(VkPhysicalDevice) * n);
  vkEnumeratePhysicalDevices(vk->inst, &n, list);
  vk->phys = list[0];
  for (uint32_t i = 0; i < n; ++i) {
    VkPhysicalDeviceProperties p; vkGetPhysicalDeviceProperties(list[i], &p);
    if (p.deviceType == VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU) { vk->phys = list[i]; break; }
  }
  free(list);
  return 0;
}

static VkShaderModule shader(RtVk* vk, const unsigned char* words, size_t bytes) {
  VkShaderModuleCreateInfo ci = { .sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,
    .codeSize = bytes, .pCode = (const uint32_t*)words };
  VkShaderModule m = VK_NULL_HANDLE;
  if (vkCreateShaderModule(vk->dev, &ci, NULL, &m) != VK_SUCCESS) return VK_NULL_HANDLE;
  return m;
}

static VkPipeline make_pipeline(RtVk* vk, VkShaderModule sm, int spec,
                                int bm, int bn, int bk) {
  VkSpecializationMapEntry me[3] = {
    { .constantID=0, .offset=0, .size=sizeof(int) },
    { .constantID=1, .offset=sizeof(int), .size=sizeof(int) },
    { .constantID=2, .offset=2*sizeof(int), .size=sizeof(int) },
  };
  int vals[3] = { bm, bn, bk };
  VkSpecializationInfo si = { .mapEntryCount=3, .pMapEntries=me,
    .dataSize=sizeof(vals), .pData=vals };
  VkPipelineShaderStageCreateInfo st = { .sType=VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO,
    .stage=VK_SHADER_STAGE_COMPUTE_BIT, .module=sm, .pName="main",
    .pSpecializationInfo = spec ? &si : NULL };
  VkComputePipelineCreateInfo ci = { .sType=VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO,
    .stage=st, .layout=vk->playout };
  VkPipeline p = VK_NULL_HANDLE;
  vkCreateComputePipelines(vk->dev, vk->pcache, 1, &ci, NULL, &p);
  return p;
}

void rt_vk_init(RT* c) {
  RtVk* vk = (RtVk*)calloc(1, sizeof(RtVk));
  c->vk = vk;
  VkApplicationInfo app = { .sType=VK_STRUCTURE_TYPE_APPLICATION_INFO,
    .pApplicationName="bitsy-rt", .apiVersion=VK_API_VERSION_1_2 };
  VkInstanceCreateInfo ici = { .sType=VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO, .pApplicationInfo=&app };
  if (vkCreateInstance(&ici, NULL, &vk->inst) != VK_SUCCESS) return;
  if (select_phys(vk)) return;

  uint32_t nf = 0;
  vkGetPhysicalDeviceQueueFamilyProperties(vk->phys, &nf, NULL);
  VkQueueFamilyProperties* fam = (VkQueueFamilyProperties*)malloc(sizeof(VkQueueFamilyProperties)*nf);
  vkGetPhysicalDeviceQueueFamilyProperties(vk->phys, &nf, fam);
  vk->qfam = 0;
  for (uint32_t i=0;i<nf;++i) if (fam[i].queueFlags & VK_QUEUE_COMPUTE_BIT) { vk->qfam=i; break; }
  free(fam);

  float prio = 1.0f;
  VkDeviceQueueCreateInfo qci = { .sType=VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO,
    .queueFamilyIndex=vk->qfam, .queueCount=1, .pQueuePriorities=&prio };
  VkPhysicalDeviceBufferDeviceAddressFeatures bda = {
    .sType=VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_BUFFER_DEVICE_ADDRESS_FEATURES,
    .bufferDeviceAddress=VK_TRUE };
  VkPhysicalDeviceFeatures feats = {0};
  VkDeviceCreateInfo dci = { .sType=VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO,
    .queueCreateInfoCount=1, .pQueueCreateInfos=&qci, .pEnabledFeatures=&feats, .pNext=&bda };
  if (vkCreateDevice(vk->phys, &dci, NULL, &vk->dev) != VK_SUCCESS) return;
  vkGetDeviceQueue(vk->dev, vk->qfam, 0, &vk->queue);

  VkCommandPoolCreateInfo pci = { .sType=VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO,
    .queueFamilyIndex=vk->qfam, .flags=VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT };
  vkCreateCommandPool(vk->dev, &pci, NULL, &vk->pool);
  VkCommandBufferAllocateInfo ai = { .sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO,
    .commandPool=vk->pool, .level=VK_COMMAND_BUFFER_LEVEL_PRIMARY, .commandBufferCount=2 };
  vkAllocateCommandBuffers(vk->dev, &ai, &vk->cmd); /* cmd[0], cmd[1] contiguous */

  VkFenceCreateInfo fci = { .sType=VK_STRUCTURE_TYPE_FENCE_CREATE_INFO };
  vkCreateFence(vk->dev, &fci, NULL, &vk->fence);

  VkSemaphoreTypeCreateInfo stci = { .sType=VK_STRUCTURE_TYPE_SEMAPHORE_TYPE_CREATE_INFO,
    .semaphoreType=VK_SEMAPHORE_TYPE_TIMELINE, .initialValue=0 };
  VkSemaphoreCreateInfo sci = { .sType=VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO, .pNext=&stci };
  vkCreateSemaphore(vk->dev, &sci, NULL, &vk->timeline);

  /* descriptor set: binding0 params, binding1 output */
  VkDescriptorSetLayoutBinding binds[2] = {
    { .binding=0, .descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, .descriptorCount=1, .stageFlags=VK_SHADER_STAGE_COMPUTE_BIT },
    { .binding=1, .descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, .descriptorCount=1, .stageFlags=VK_SHADER_STAGE_COMPUTE_BIT },
  };
  VkDescriptorSetLayoutCreateInfo slci = { .sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO,
    .bindingCount=2, .pBindings=binds };
  vkCreateDescriptorSetLayout(vk->dev, &slci, NULL, &vk->set_layout);
  VkPushConstantRange pcr = { .stageFlags=VK_SHADER_STAGE_COMPUTE_BIT, .offset=0, .size=16 };
  VkPipelineLayoutCreateInfo plci = { .sType=VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO,
    .setLayoutCount=1, .pSetLayouts=&vk->set_layout, .pushConstantRangeCount=1, .pPushConstantRanges=&pcr };
  vkCreatePipelineLayout(vk->dev, &plci, NULL, &vk->playout);
  VkDescriptorPoolSize ps = { .type=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, .descriptorCount=2 };
  VkDescriptorPoolCreateInfo dpci = { .sType=VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO,
    .maxSets=1, .poolSizeCount=1, .pPoolSizes=&ps };
  vkCreateDescriptorPool(vk->dev, &dpci, NULL, &vk->dpool);
  VkDescriptorSetAllocateInfo dsai = { .sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO,
    .descriptorPool=vk->dpool, .descriptorSetCount=1, .pSetLayouts=&vk->set_layout };
  vkAllocateDescriptorSets(vk->dev, &dsai, &vk->set);

  VkPipelineCacheCreateInfo pcc = { .sType=VK_STRUCTURE_TYPE_PIPELINE_CACHE_CREATE_INFO };
  vkCreatePipelineCache(vk->dev, &pcc, NULL, &vk->pcache);

  VkShaderModule sf = shader(vk, rt_fused_spv, rt_fused_spv_bytes);
  VkShaderModule sg = shader(vk, rt_gemm_spv, rt_gemm_spv_bytes);
  VkShaderModule sr = shader(vk, rt_reduce_spv, rt_reduce_spv_bytes);
  vk->fused[0] = make_pipeline(vk, sf, 0, 0,0,0);
  vk->gemm[0] = make_pipeline(vk, sg, 1, 16,16,16);
  vk->gemm[1] = make_pipeline(vk, sg, 1, 32,32,16);
  vk->gemm[2] = make_pipeline(vk, sg, 1, 64,64,16);
  vk->reduce = make_pipeline(vk, sr, 0, 0,0,0);

  /* params + output staging buffers (host visible) */
  VkBufferCreateInfo bci = { .sType=VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,
    .size=64*1024, .usage=VK_BUFFER_USAGE_STORAGE_BUFFER_BIT };
  VkMemoryAllocateFlagsInfo mfi = { .sType=VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_FLAGS_INFO,
    .flags=VK_MEMORY_ALLOCATE_DEVICE_ADDRESS_BIT };
  VkMemoryRequirements req;
  vkCreateBuffer(vk->dev, &bci, NULL, &vk->params);
  vkGetBufferMemoryRequirements(vk->dev, vk->params, &req);
  uint32_t mt=0; VkPhysicalDeviceMemoryProperties mp; vkGetPhysicalDeviceMemoryProperties(vk->phys,&mp);
  for(uint32_t i=0;i<mp.memoryTypeCount;++i) if((req.memoryTypeBits&(1u<<i)) &&
    (mp.memoryTypes[i].propertyFlags & VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT) &&
    (mp.memoryTypes[i].propertyFlags & VK_MEMORY_PROPERTY_HOST_COHERENT_BIT)){mt=i;break;}
  VkMemoryAllocateInfo mai = { .sType=VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO,
    .allocationSize=req.size, .memoryTypeIndex=mt, .pNext=&mfi };
  vkAllocateMemory(vk->dev, &mai, NULL, &vk->params_mem);
  vkBindBufferMemory(vk->dev, vk->params, vk->params_mem, 0);
  vkMapMemory(vk->dev, vk->params_mem, 0, req.size, 0, &vk->params_map);

  vkCreateBuffer(vk->dev, &bci, NULL, &vk->out);
  vkGetBufferMemoryRequirements(vk->dev, vk->out, &req);
  mai.allocationSize=req.size;
  vkAllocateMemory(vk->dev, &mai, NULL, &vk->out_mem);
  vkBindBufferMemory(vk->dev, vk->out, vk->out_mem, 0);
  vkMapMemory(vk->dev, vk->out_mem, 0, req.size, 0, &vk->out_map);

  VkDescriptorBufferInfo pinfo = { .buffer=vk->params, .offset=0, .range=64*1024 };
  VkDescriptorBufferInfo oinfo = { .buffer=vk->out, .offset=0, .range=64*1024 };
  VkWriteDescriptorSet w[2] = {
    { .sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET, .dstSet=vk->set, .dstBinding=0,
      .descriptorCount=1, .descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, .pBufferInfo=&pinfo },
    { .sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET, .dstSet=vk->set, .dstBinding=1,
      .descriptorCount=1, .descriptorType=VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, .pBufferInfo=&oinfo },
  };
  vkUpdateDescriptorSets(vk->dev, 2, w, 0, NULL);
}

void rt_vk_shutdown(RT* c) {
  RtVk* vk = c->vk; if (!vk || !vk->dev) return;
  vkDeviceWaitIdle(vk->dev);
  vkDestroySemaphore(vk->dev, vk->timeline, NULL);
  vkDestroyFence(vk->dev, vk->fence, NULL);
  vkDestroyPipelineCache(vk->dev, vk->pcache, NULL);
  vkDestroyDescriptorPool(vk->dev, vk->dpool, NULL);
  vkDestroyDescriptorSetLayout(vk->dev, vk->set_layout, NULL);
  vkDestroyPipelineLayout(vk->dev, vk->playout, NULL);
  vkDestroyCommandPool(vk->dev, vk->pool, NULL);
  vkDestroyBuffer(vk->dev, vk->params, NULL); vkFreeMemory(vk->dev, vk->params_mem, NULL);
  vkDestroyBuffer(vk->dev, vk->out, NULL); vkFreeMemory(vk->dev, vk->out_mem, NULL);
  vkDestroyDevice(vk->dev, NULL); vkDestroyInstance(vk->inst, NULL);
  free(vk); c->vk = NULL;
}

/* Allocate a device buffer and upload host data; store handle in RtBuf->vk. */
static RtVkBuf* vkbuf(RT* c, RtBuf* b) {
  RtVk* vk = c->vk;
  if (b->vk) return (RtVkBuf*)b->vk;
  RtVkBuf* vb = (RtVkBuf*)calloc(1, sizeof(RtVkBuf));
  VkDeviceSize sz = sizeof(float) * (size_t)(b->n ? b->n : 1);
  VkBufferCreateInfo bci = { .sType=VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,
    .size=sz, .usage=VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT |
                      VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT };
  vkCreateBuffer(vk->dev, &bci, NULL, &vb->buf);
  VkMemoryRequirements req; vkGetBufferMemoryRequirements(vk->dev, vb->buf, &req);
  uint32_t mt=0; VkPhysicalDeviceMemoryProperties mp; vkGetPhysicalDeviceMemoryProperties(vk->phys,&mp);
  for(uint32_t i=0;i<mp.memoryTypeCount;++i) if((req.memoryTypeBits&(1u<<i)) &&
    (mp.memoryTypes[i].propertyFlags & VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT) &&
    (mp.memoryTypes[i].propertyFlags & VK_MEMORY_PROPERTY_HOST_COHERENT_BIT)){mt=i;break;}
  VkMemoryAllocateFlagsInfo mfi = { .sType=VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_FLAGS_INFO,
    .flags=VK_MEMORY_ALLOCATE_DEVICE_ADDRESS_BIT };
  VkMemoryAllocateInfo ai = { .sType=VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO,
    .allocationSize=req.size, .memoryTypeIndex=mt, .pNext=&mfi };
  vkAllocateMemory(vk->dev, &ai, NULL, &vb->mem);
  vkBindBufferMemory(vk->dev, vb->buf, vb->mem, 0);
  VkBufferDeviceAddressInfo adi = { .sType=VK_STRUCTURE_TYPE_BUFFER_DEVICE_ADDRESS_INFO, .buffer=vb->buf };
  vb->addr = vkGetBufferDeviceAddress(vk->dev, &adi);
  vb->size = sz;
  if (b->host) { void* m; vkMapMemory(vk->dev, vb->mem, 0, sz, 0, &m);
    memcpy(m, b->host, sz); vkUnmapMemory(vk->dev, vb->mem); }
  b->vk = vb;
  return vb;
}

static void pack_addr(int* p, int idx, uint64_t a) {
  p[idx] = (int)(uint32_t)(a & 0xffffffffu);
  p[idx+1] = (int)(uint32_t)(a >> 32);
}

static void submit_wait(RtVk* vk) {
  VkSubmitInfo si = { .sType=VK_STRUCTURE_TYPE_SUBMIT_INFO, .commandBufferCount=1, .pCommandBuffers=&vk->cmd };
  vkQueueSubmit(vk->queue, 1, &si, vk->fence);
  vkWaitForFences(vk->dev, 1, &vk->fence, VK_TRUE, UINT64_MAX);
  vkResetFences(vk->dev, 1, &vk->fence);
}

void rt_vk_fused(RT* c, RtFusion* f, RtBuf* out) {
  RtVk* vk = c->vk; if (!vk->dev) return;
  int* p = (int*)vk->params_map;
  p[0]=out->n; p[1]=f->ninst; p[2]=f->ninputs; p[3]=f->ndim;
  for (int j=0;j<f->ndim;++j) p[4+j]=(int)f->dims[j];
  for (int i=0;i<f->ninputs;++i) {
    RtVkBuf* vb = vkbuf(c, f->in_buf[i]);
    for (int j=0;j<RT_MAXDIMS;++j) p[8+i*RT_MAXDIMS+j]=(int)f->in_stride[i][j];
    pack_addr(p, 40+i*2, vb->addr);
  }
  for (int k=0;k<f->ninst;++k) {
    RtInst in = f->inst[k]; int b=56+k*4;
    p[b]=in.op; p[b+1]=in.a; p[b+2]=in.b;
    memcpy(&p[b+3], &in.c, sizeof(float));
  }
  VkCommandBufferBeginInfo bi = { .sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO };
  vkBeginCommandBuffer(vk->cmd, &bi);
  vkCmdBindPipeline(vk->cmd, VK_PIPELINE_BIND_POINT_COMPUTE, vk->fused[0]);
  vkCmdBindDescriptorSets(vk->cmd, VK_PIPELINE_BIND_POINT_COMPUTE, vk->playout, 0,1,&vk->set,0,NULL);
  int pc[4] = { out->n, f->ninst, f->ninputs, f->ndim };
  vkCmdPushConstants(vk->cmd, vk->playout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(pc), pc);
  vkCmdDispatch(vk->cmd, (out->n+255)/256, 1, 1);
  vkEndCommandBuffer(vk->cmd);
  submit_wait(vk);
  memcpy(out->host, vk->out_map, sizeof(float)*(size_t)out->n);
}

void rt_vk_gemm(RT* c, RtBuf* a, RtBuf* b, RtBuf* out) {
  RtVk* vk=c->vk; if(!vk->dev) return;
  int M=(int)a->dims[0],K=(int)a->dims[1],N=(int)b->dims[1];
  int* p=(int*)vk->params_map;
  p[0]=M;p[1]=N;p[2]=K;
  pack_addr(p,4,vkbuf(c,a)->addr); pack_addr(p,6,vkbuf(c,b)->addr); pack_addr(p,8,vkbuf(c,out)->addr);
  VkCommandBufferBeginInfo bi={.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
  vkBeginCommandBuffer(vk->cmd,&bi);
  vkCmdBindPipeline(vk->cmd,VK_PIPELINE_BIND_POINT_COMPUTE,vk->gemm[0]);
  vkCmdBindDescriptorSets(vk->cmd,VK_PIPELINE_BIND_POINT_COMPUTE,vk->playout,0,1,&vk->set,0,NULL);
  int pc[4]={M,N,K,0}; vkCmdPushConstants(vk->cmd,vk->playout,VK_SHADER_STAGE_COMPUTE_BIT,0,sizeof(pc),pc);
  vkCmdDispatch(vk->cmd, ((M+15)/16)*((N+15)/16), 1,1);
  vkEndCommandBuffer(vk->cmd);
  submit_wait(vk);
  /* result written directly to C buffer; copy back from its device memory */
  void* m; vkMapMemory(vk->dev, ((RtVkBuf*)out->vk)->mem, 0, sizeof(float)*(size_t)out->n,0,&m);
  memcpy(out->host,m,sizeof(float)*(size_t)out->n); vkUnmapMemory(vk->dev,((RtVkBuf*)out->vk)->mem);
}

void rt_vk_reduce(RT* c, RtBuf* in, int axis, RtBuf* out) {
  RtVk* vk=c->vk; if(!vk->dev) return;
  int outer=1,stride=(int)in->dims[axis],inner=1;
  for(int i=0;i<axis;++i)outer*=(int)in->dims[i];
  for(int i=axis+1;i<in->ndim;++i)inner*=(int)in->dims[i];
  int* p=(int*)vk->params_map; p[0]=outer;p[1]=stride;p[2]=inner;
  pack_addr(p,4,vkbuf(c,in)->addr); pack_addr(p,6,vkbuf(c,out)->addr);
  VkCommandBufferBeginInfo bi={.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
  vkBeginCommandBuffer(vk->cmd,&bi);
  vkCmdBindPipeline(vk->cmd,VK_PIPELINE_BIND_POINT_COMPUTE,vk->reduce);
  vkCmdBindDescriptorSets(vk->cmd,VK_PIPELINE_BIND_POINT_COMPUTE,vk->playout,0,1,&vk->set,0,NULL);
  int total=outer*inner; int pc[4]={total,0,0,0};
  vkCmdPushConstants(vk->cmd,vk->playout,VK_SHADER_STAGE_COMPUTE_BIT,0,sizeof(pc),pc);
  vkCmdDispatch(vk->cmd,(total+255)/256,1,1);
  vkEndCommandBuffer(vk->cmd);
  submit_wait(vk);
  void* m; vkMapMemory(vk->dev,((RtVkBuf*)out->vk)->mem,0,sizeof(float)*(size_t)out->n,0,&m);
  memcpy(out->host,m,sizeof(float)*(size_t)out->n); vkUnmapMemory(vk->dev,((RtVkBuf*)out->vk)->mem);
}

void rt_vk_capture_begin(RT* c){ RtVk* vk=c->vk; if(vk&&vk->dev){ VkCommandBufferBeginInfo bi={.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO}; vkBeginCommandBuffer(vk->replay_cmd,&bi);} }
void rt_vk_capture_end(RT* c){ RtVk* vk=c->vk; if(vk&&vk->dev) vkEndCommandBuffer(vk->replay_cmd); }
void rt_vk_replay(RT* c){
  RtVk* vk=c->vk; if(!vk||!vk->dev||!vk->replay_count)return;
  vk->tick++;
  VkSemaphoreSubmitInfo w={.sType=VK_STRUCTURE_TYPE_SEMAPHORE_SUBMIT_INFO,.semaphore=vk->timeline,.value=vk->tick-1,.stageMask=VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT};
  VkSemaphoreSubmitInfo s={.sType=VK_STRUCTURE_TYPE_SEMAPHORE_SUBMIT_INFO,.semaphore=vk->timeline,.value=vk->tick,.stageMask=VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT};
  VkCommandBufferSubmitInfo cb={.sType=VK_STRUCTURE_TYPE_COMMAND_BUFFER_SUBMIT_INFO,.commandBuffer=vk->replay_cmd};
  VkSubmitInfo2 si={.sType=VK_STRUCTURE_TYPE_SUBMIT_INFO_2,.waitSemaphoreInfoCount=1,.pWaitSemaphoreInfos=&w,.commandBufferInfoCount=1,.pCommandBufferInfos=&cb,.signalSemaphoreInfoCount=1,.pSignalSemaphoreInfos=&s};
  vkQueueSubmit2(vk->queue,1,&si,VK_NULL_HANDLE);
  VkSemaphoreWaitInfo wi={.sType=VK_STRUCTURE_TYPE_SEMAPHORE_WAIT_INFO,.semaphoreCount=1,.pSemaphores=&vk->timeline,.pValues=&vk->tick};
  vkWaitSemaphores(vk->dev,&wi,UINT64_MAX);
}
#else
/* CPU-only build: no Vulkan device. */
void rt_vk_init(RT* c){ (void)c; }
void rt_vk_shutdown(RT* c){ (void)c; }
void rt_vk_fused(RT* c, RtFusion* f, RtBuf* o){ (void)c;(void)f;(void)o; }
void rt_vk_gemm(RT* c, RtBuf* a, RtBuf* b, RtBuf* o){ (void)c;(void)a;(void)b;(void)o; }
void rt_vk_reduce(RT* c, RtBuf* i, int ax, RtBuf* o){ (void)c;(void)i;(void)ax;(void)o; }
void rt_vk_capture_begin(RT* c){ (void)c; }
void rt_vk_capture_end(RT* c){ (void)c; }
void rt_vk_replay(RT* c){ (void)c; }
#endif
